def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    FINAL_EXPLOIT = 94

    my_d = 0
    opp_c = 0
    opp_d = 0
    sucker = 0
    unprovoked = 0
    punished = 0
    forgiven = 0

    for i in range(n):
        me, op = history[i]
        if me == 'D':
            my_d += 1
        if op == 'C':
            opp_c += 1
        else:
            opp_d += 1

        if me == 'C' and op == 'D':
            sucker += 1
            if i == 0 or history[i - 1][0] == 'C':
                unprovoked += 1

        if me == 'D' and op == 'C':
            if i + 1 < n:
                if history[i + 1][1] == 'D':
                    punished += 1
                else:
                    forgiven += 1

    if opp_d == 0:
        if n < FINAL_EXPLOIT:
            return 'C'
        if my_d == 0:
            return 'D'
        if my_d == 1 and history[-1][0] == 'D' and n < 99:
            return 'C'
        return 'D'

    look = n if n < 8 else 8
    start = n - look

    recent_opp_d = 0
    recent_sucker = 0
    recent_unprovoked = 0

    for i in range(start, n):
        me, op = history[i]
        if op == 'D':
            recent_opp_d += 1
        if me == 'C' and op == 'D':
            recent_sucker += 1
            if i == 0 or history[i - 1][0] == 'C':
                recent_unprovoked += 1

    last_my, last_opp = history[-1]

    cd_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'C' and history[i][1] == 'D':
        cd_streak += 1
        i -= 1

    dc_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D' and history[i][1] == 'C':
        dc_streak += 1
        i -= 1

    opp_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_d_streak += 1
        i -= 1

    if opp_c * 100 <= 42 * n:
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if opp_c * 100 <= 50 * n or opp_d_streak >= 2 or recent_opp_d >= 4:
                return 'D'
            return 'C'

        if cd_streak >= 2 or opp_d_streak >= 2:
            return 'D'

        if opp_c * 100 <= 55 * n or recent_unprovoked >= 2 or unprovoked >= 2:
            return 'D'

        if (opp_c * 100 >= 75 * n and unprovoked <= 1 and recent_sucker <= 1
                and opp_d_streak <= 1):
            return 'C'

        return 'D'

    if last_my == 'D':
        prev_cd = False
        prev_dd = False
        if n >= 2:
            pm, po = history[-2]
            if pm == 'C' and po == 'D':
                prev_cd = True
            elif pm == 'D' and po == 'D':
                prev_dd = True

        if dc_streak >= 2 or prev_cd or prev_dd:
            return 'D'

        if forgiven > punished and opp_c * 100 >= 50 * n:
            return 'D'

        if opp_c * 100 <= 45 * n:
            return 'D'

        return 'C'

    if opp_c * 100 <= 60 * n or recent_opp_d >= 4:
        return 'D'

    if (forgiven >= 2 and forgiven > punished * 2 + 1
            and opp_c * 100 >= 70 * n):
        return 'D'

    return 'C'
